import React, { useState, useEffect } from "react";
import "../styles/CreateArticlesAdmin.css";

export default function CreateArticlePage() {
  const [formData, setFormData] = useState({
    title: "",
    slug: "",
    content: "",
    excerpt: "",
    status: "draft",
    type: "standard", // <-- "standard" або "interactive"
    category: "sport",
    is_premium: false,
    image: null,
    channel: "", // id каналу (можна залишити пустим)
  });

  // тільки для poll
  const [pollQuestion, setPollQuestion] = useState("");
  const [pollOptions, setPollOptions] = useState(["", ""]); // дві опції за замовчуванням

  const [channels, setChannels] = useState([]);
  const [loading, setLoading] = useState(false);

  const token = localStorage.getItem("token");

  useEffect(() => {
    // підвантажити канали для select (опціонально)
    const fetchChannels = async () => {
      try {
        const res = await fetch("http://127.0.0.1:8000/api/channels/", {
          headers: { ...(token && { Authorization: `Bearer ${token}` }) },
        });
        if (res.ok) {
          const data = await res.json();
          setChannels(Array.isArray(data) ? data : data.results || []);
        }
      } catch (err) {
        console.error("Не вдалося завантажити канали", err);
      }
    };
    fetchChannels();
  }, [token]);

  const handleChange = (e) => {
    const { name, value, type: t, checked, files } = e.target;
    if (t === "checkbox") setFormData((s) => ({ ...s, [name]: checked }));
    else if (t === "file") setFormData((s) => ({ ...s, [name]: files[0] || null }));
    else setFormData((s) => ({ ...s, [name]: value }));
  };

  // Poll option handlers
  const handleOptionChange = (idx, val) => {
    setPollOptions((prev) => prev.map((o, i) => (i === idx ? val : o)));
  };
  const addOption = () => setPollOptions((p) => [...p, ""]);
  const removeOption = (idx) => setPollOptions((p) => p.filter((_, i) => i !== idx));

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      // 1) створюємо Article (FormData для файлу)
      const fd = new FormData();
      fd.append("title", formData.title);
      fd.append("slug", formData.slug);
      fd.append("content", formData.content);
      fd.append("excerpt", formData.excerpt || "");
      fd.append("status", formData.status);
      fd.append("type", formData.type);
      fd.append("category", formData.category);
      fd.append("is_premium", formData.is_premium ? "true" : "false");
      if (formData.image) fd.append("image", formData.image);
      if (formData.channel) fd.append("channel", formData.channel);

      const articleRes = await fetch("http://127.0.0.1:8000/api/articles/", {
        method: "POST",
        headers: {
          ...(token && { Authorization: `Bearer ${token}` }),
          // НЕ ставити "Content-Type": browser поставить multipart boundary сам
        },
        body: fd,
      });

      if (!articleRes.ok) {
        const errorBody = await articleRes.json().catch(() => null);
        console.error("Помилка створення article:", articleRes.status, errorBody);
        alert(`Помилка створення статті: ${JSON.stringify(errorBody)}`);
        setLoading(false);
        return;
      }

      const articleData = await articleRes.json();
      // якщо тип interactive — створюємо poll
      if (formData.type === "interactive") {
        // валідація poll
        const optionsTrimmed = pollOptions.map((o) => o.trim()).filter(Boolean);
        if (!pollQuestion.trim() || optionsTrimmed.length < 2) {
          alert("Опитування має питання і щонайменше 2 непорожні варіанти.");
          setLoading(false);
          return;
        }

        const pollPayload = {
          article: articleData.id,
          question: pollQuestion,
          options: optionsTrimmed,
        };

        const pollRes = await fetch("http://127.0.0.1:8000/api/polls/", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
          body: JSON.stringify(pollPayload),
        });

        if (!pollRes.ok) {
          const err = await pollRes.json().catch(() => null);
          console.error("Помилка створення опитування:", err);
          alert("Статтю створено, але не вдалося створити опитування. Подивись лог.");
          setLoading(false);
          return;
        }
      }

      alert("✅ Успішно створено!");
      window.location.href = "/";
    } catch (err) {
      console.error("Помилка сабміту:", err);
      alert("Помилка під час створення.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="create-article-container">
      <h2>Створити — Статтю або Опитування</h2>

      <form className="create-article-form" onSubmit={handleSubmit} encType="multipart/form-data">
        <label>Тип контенту:</label>
        <select
          name="type"
          value={formData.type}
          onChange={(e) => setFormData((s) => ({ ...s, type: e.target.value }))}
        >
          <option value="standard">Стаття</option>
          <option value="interactive">Опитування</option>
        </select>

        {/* Загальні поля (і для статті, і для опитування) */}
        <input name="title" placeholder="Заголовок" value={formData.title} onChange={handleChange} required />
        <input name="slug" placeholder="Slug" value={formData.slug} onChange={handleChange} required />
        <textarea name="content" placeholder="Текст (для опитування можна залишити короткий опис)" value={formData.content} onChange={handleChange} />

        <textarea name="excerpt" placeholder="Короткий опис" value={formData.excerpt} onChange={handleChange} />

        <label>Статус:</label>
        <select name="status" value={formData.status} onChange={handleChange}>
          <option value="draft">Чернетка</option>
          <option value="published">Опубліковано</option>
        </select>

        <label>Категорія:</label>
        <select name="category" value={formData.category} onChange={handleChange}>
          <option value="sport">Спорт</option>
          <option value="fashion">Мода</option>
          <option value="News">Новини</option>
        </select>

        <label>
          <input type="checkbox" name="is_premium" checked={formData.is_premium} onChange={handleChange} />
          Преміум
        </label>

        <label>Канал (постити в канал):</label>
        <select name="channel" value={formData.channel} onChange={handleChange}>
          <option value="">-- Жодного --</option>
          {channels.map((c) => (
            <option key={c.id} value={c.id}>{c.name}</option>
          ))}
        </select>

        <label>Картинка (опціонально):</label>
        <input type="file" name="image" accept="image/*" onChange={handleChange} />

        {/* Умовні поля для опитування */}
        {formData.type === "interactive" && (
          <div className="poll-block">
            <h3>Налаштування опитування</h3>
            <input
              placeholder="Питання опитування"
              value={pollQuestion}
              onChange={(e) => setPollQuestion(e.target.value)}
              required
            />

            <div>
              <label>Варіанти відповіді:</label>
              {pollOptions.map((opt, idx) => (
                <div key={idx} style={{ display: "flex", gap: 8, marginBottom: 6 }}>
                  <input
                    value={opt}
                    onChange={(e) => handleOptionChange(idx, e.target.value)}
                    placeholder={`Варіант ${idx + 1}`}
                    required
                  />
                  {pollOptions.length > 2 && (
                    <button type="button" onClick={() => removeOption(idx)}>✖</button>
                  )}
                </div>
              ))}
              <button type="button" onClick={addOption}>Додати варіант</button>
            </div>
          </div>
        )}

        <button type="submit" disabled={loading}>{loading ? "Зачекайте..." : "Створити"}</button>
      </form>
    </div>
  );
}
